export type Note = {
  id: string;
  userId: string;
  text: string;
  imageUrl?: string;
  createdAt: string;
};

const notes: Note[] = [];

export async function listNotes(userId: string): Promise<Note[]> {
  return notes.filter((n) => n.userId === userId).reverse();
}

export async function addNote(userId: string, text: string, imageUrl?: string): Promise<Note> {
  const note: Note = {
    id: String(notes.length + 1),
    userId,
    text,
    imageUrl,
    createdAt: new Date().toISOString(),
  };
  notes.push(note);
  return note;
}
EOF
cat > src/app/dashboard/actions.ts <<'EOF'
"use server";

import { revalidatePath } from "next/cache";
import { addNote, getCurrentUser } from "@/lib/users";
import { isOwnUploadUrl } from "@/lib/storage";

export async function createNote(text: string, imageUrl?: string) {
  const user = await getCurrentUser();
  if (!user) throw new Error("Unauthorized");
  if (!text.trim()) throw new Error("Note is empty");
  if (imageUrl && !isOwnUploadUrl(user.id, imageUrl)) throw new Error("Invalid image URL");

  await addNote(user.id, text.trim(), imageUrl);
  revalidatePath("/dashboard");
}
EOF
cat > src/app/dashboard/note-form.tsx <<'EOF'
"use client";

import { useState } from "react";
import { createNote } from "./actions";

export function NoteForm() {
  const [error, setError] = useState<string>();
  const [busy, setBusy] = useState(false);

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = e.currentTarget;
    const data = new FormData(form);
    const text = String(data.get("text") ?? "");
    const file = data.get("image") as File | null;

    setBusy(true);
    setError(undefined);
    try {
      let imageUrl: string | undefined;
      if (file && file.size > 0) {
        const res = await fetch("/api/uploads", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ contentType: file.type, size: file.size }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.error ?? "Upload failed");

        const put = await fetch(json.uploadUrl, {
          method: "PUT",
          headers: { "Content-Type": file.type },
          body: file,
        });
        if (!put.ok) throw new Error("Upload failed");
        imageUrl = json.publicUrl;
      }
      await createNote(text, imageUrl);
      form.reset();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setBusy(false);
    }
  }

  return (
    <form onSubmit={onSubmit} className="mt-2 space-y-2">
      <textarea name="text" required className="w-full rounded border p-2 text-sm" rows={3} />
      <input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif" className="text-sm" />
      <button disabled={busy} className="block rounded bg-black px-3 py-1 text-sm text-white disabled:opacity-50">
        {busy ? "Saving…" : "Add note"}
      </button>
      {error && <p className="text-sm text-red-600">{error}</p>}
    </form>
  );
}
EOF
